    struct IdleTimeoutStream<S> {
        #[pin]
        inner: S,
        #[pin]
        deadline: Sleep,
        timeout: Duration,
        timed_out: bool,
    }
}

impl<S> IdleTimeoutStream<S> {
    fn new(inner: S, timeout: Duration) -> Self {
        Self {
            inner,
            deadline: tokio::time::sleep(timeout),
            timeout,
            timed_out: false,
        }
    }
}

